/**
 * Return type for dataPill that handles TableAwareRecord types from OutputsWithDotwalk.
 * - TableAwareRecord objects: returns string | any for compatibility with reference types
 * - Other types: returns T to preserve type checking
 */
type DataPillReturn<T> =
    T extends Record<string, unknown>
        ? // biome-ignore lint/suspicious/noExplicitAny: TableAwareRecord needs flexible type for reference compatibility
          string | any // TableAwareRecord - compatible with string | Record<T> | ExplicitKey<T>
        : T // Not an object, preserve type

/**
 * Wrapper function for datapill expressions that provides type information.
 * This function wraps PropertyAccess expressions and associates them with their data type
 * for proper serialization to Flow Designer XML format.
 *
 * At runtime, this function is a passthrough that returns the expression unchanged.
 * The type information is used at compile/build time by the build plugins.
 *
 * Special handling: TableAwareRecord types from OutputsWithDotwalk are accepted without
 * strict type checking, as they represent expanded reference types with dotwalk support.
 *
 * @template T - The type of the expression being wrapped
 * @param _expression - The datapill expression (e.g., params.trigger.current.active)
 * @param _type - The data type of the datapill value
 * @returns The same expression (passthrough at runtime)
 *
 * @example
 * // Boolean trigger field
 * wfa.dataPill(params.trigger.current.active, 'boolean')
 *
 * // String flow variable
 * wfa.dataPill(params.flowVariables.userName, 'string')
 *
 * // Reference field with dot-walking
 * wfa.dataPill(params.trigger.current.assigned_to.email, 'string')
 *
 * // Reference field with TableAwareRecord (from OutputsWithDotwalk)
 * wfa.dataPill(params.flowVariables.userRef, 'reference')
 *
 * // Action output reference
 * wfa.dataPill(createIncident.record, 'reference')
 *
 * // In template literals
 * `Hello ${wfa.dataPill(params.flowVariables.userName, 'string')}`
 */
export function dataPill<T>(_expression: T, _type: FlowDataType): DataPillReturn<T> {
    // Runtime passthrough - the build plugins extract type info at compile time
    // biome-ignore lint/suspicious/noExplicitAny: Type coercion for TableAwareRecord compatibility
    return _expression as any
}

/**
 * Creates an inline script for use in Flow Designer action/subflow inputs.
 *
 * Inline scripts are JavaScript code that executes server-side during flow execution.
 * They have access to flow context via `fd_data` and can return any type of value.
 *
 * @param script - The JavaScript code to execute. Should be a valid expression or statements.
 * @returns The result of the script execution (any type at runtime)
 *
 */
// biome-ignore lint/suspicious/noExplicitAny: InlineScript returns dynamic script result
export function InlineScript(script: string): any {
    // This function is a marker for the build system to detect inline scripts
    // At runtime in Flow Designer, the script will be executed server-side
    return script
}

/**
 * Rule type determining approval logic:
 * - 'Any': Any user or any group member can approve or reject
 * - 'All': All users and all group members need to approve or reject
 * - 'Res': All responded and anyone approves or rejects
 * - 'Count': Specific number of approvals required to approve or reject
 * - 'Percent': Percentage of approvals required to approve or reject
 */
export type ApprovalConditionRuleType = 'Any' | 'All' | 'Res' | 'Count' | 'Percent'

export type ApprovalRuleConditionType = {
    ruleType: ApprovalConditionRuleType

    /** List of users who can approve/reject
     * Will be empty if manual is true
     */
    users?: Array<unknown>

    /** List of groups whose members can approve/reject
     * Will be empty if manual is true
     */
    groups?: Array<unknown>

    /** Required number of approvals (only for 'Count' rule_type)
     */
    count?: number

    /** Required percentage of approvals (only for 'Percent' rule_type) */
    percent?: number

    /** Whether manual approval is required (no auto-approval) */
    manual?: boolean
}
/** Action type: 'Approves' (approve only), 'Rejects' (reject only), or 'ApprovesRejects' (both) */
export type ApprovalRuleActionType = 'Approves' | 'Rejects' | 'ApprovesRejects'

export type ApprovalRuleSetType = {
    action: ApprovalRuleActionType
    /** Condition type connecting rules within this set. Always 'AND' - all rules must be satisfied */
    conditionType?: 'AND'
    /** Array of individual approval rules */
    rules?: Array<ApprovalRuleConditionType>[]
}
/**
 * Defines the structure for ApprovalRules in Flow Designer.
 *
 * Approval rules determine who can approve or reject a flow and under what conditions.
 * Rules are organized into rule sets connected by OR conditions, with individual rules within
 * each set connected by AND conditions.
 *
 * @example
 * ```typescript
 * const rules: ApprovalRulesType = {
 *   conditionType: 'OR',
 *   ruleSets: [
 *     {
 *       action: 'Approves',
 *       conditionType: 'AND',
 *       rules: [
 *         {
 *           rule_type: 'Any',
 *           users: ['user1_sys_id', 'user2_sys_id'],
 *           groups: [],
 *           manual: false
 *         },
 *         {
 *           rule_type: 'All',
 *           users: [],
 *           groups: ['group_sys_id'],
 *           manual: false
 *         }
 *       ]
 *     }
 *   ]
 * }
 * ```
 */
export type ApprovalRulesType = {
    /** Condition type connecting multiple rule sets. Always 'OR' - any rule set can satisfy the approval */
    conditionType?: 'OR'
    /** Array of rule sets, each defining approval/rejection criteria */
    ruleSets?: Array<ApprovalRuleSetType>
}

/**
 * ApprovalRules configuration to use in Fluent Flows `Ask for Approval` action.
 *
 * This function converts a structured approval rules object into the string format expected
 * by ServiceNow Flow Designer. The rules define who can approve or reject a flow
 * and under what conditions.
 *
 * **Rule Structure:**
 * - Multiple rule sets are connected with OR logic (any ruleset can satisfy)
 * - Rules within a rule set are connected with AND logic (all must be satisfied)
 * - Each rule contains conditions that specify users/groups and approval requirements
 * - Conditions within a rule are connected with OR logic (any condition can satisfy)
 *
 * **Rule Types:**
 *
 * - `Any`: Any user or any group member can approve or reject
 * - `All`: All users and all group members need to approve or reject
 * - `Res`: All responded and anyone approves or rejects
 * - `Count`: Specific number of approvals required to approve or reject
 * - `Percent`: Percentage of approvals required to approve or reject
 *
 * @param approvalRules - The approval rules configuration object
 * @returns A string representation of the approval rules for Flow Designer
 *
 * @example
 * ```typescript
 * //Any user or group member from a list can approve or reject
 * const simpleRules = wfa.approvalRules({
 *   conditionType: 'OR',
 *   ruleSets: [{
 *      action: 'Approves',
 *      conditionType: 'AND',
 *      rules: [{
 *          rule_type: 'Any',
 *          users: ['user_sys_id_1', 'user_sys_id_2'],
 *          groups: [],
 *          manual: false
 *        },
 *        {
 *          rule_type: 'Any',
 *          users: ['user_sys_id_3'],
 *          groups: ['group_sys_id1'],
 *          manual: false
 *      }]
 *    },
 *    {
 *      action: 'Rejects',
 *      conditionType: 'AND',
 *      rules: [{
 *          rule_type: 'Any',
 *          users: ['user_sys_id_4', 'user_sys_id_5'],
 *          groups: ['group_sys_id_2'],
 *          manual: false
 *      }]
 *   }]
 *  })
 * ```
 */
export declare function ApprovalRules(approvalRules: ApprovalRulesType): string

/**
 * Defines the structure for Approval Due Date in Flow Designer.
 *
 * This configuration determines when approvals are due and what actions to take.
 *
 * @example
 * ```typescript
 * const dueDate: ApprovalDueDateType = {
 *   action: 'none',
 *   dateType: 'actual',
 *   date: '{}',
 *   duration: 1,
 *   durationType: 'days',
 *   daysSchedule: '',
 * }
 * ```
 */

export type ApprovalDueDateType = {
    /** Action to take on due date: 'none', 'approve', 'reject', or 'cancel' */
    action: 'none' | 'approve' | 'reject' | 'cancel'
    /** Type of date: 'actual' for specific date, 'relative' for duration-based */
    dateType?: 'actual' | 'relative'
    /** Specific date for 'actual' date_type (ISO format or expression) */
    date?: string
    /** Duration value for 'relative' date_type */
    duration?: number
    /** Duration unit: 'years', 'quarters', 'months', 'weeks', 'days', 'hours', 'minutes', 'seconds' */
    durationType?: 'years' | 'quarters' | 'months' | 'weeks' | 'days' | 'hours' | 'minutes' | 'seconds'
    /** Days Schedule for business hours calculation */
    daysSchedule?: string
}

/**
 * ApprovalDueDate configuration to use in Fluent Flows `Ask for Approval` action.
 *
 * This function converts a structured approval due date object into the format expected
 * by ServiceNow Flow Designer. The configuration determines when approvals are due and
 * what automatic action should be taken if no response is received by the due date.
 *
 * @param approvalDueDate - The approval due date configuration object
 * @returns A string representation of the approval due date for Flow Designer
 *
 * @example
 * ```typescript
 * // Approval due date with actual date for approve action
 * const dueDate = wfa.approvalDueDate({
 *   action: 'approve',
 *   dateType: 'actual',
 *   date: wfa.dataPill(_params.trigger.current.due_date, 'glide_date_time'),
 * })
 *
 * // Approval due date with relative date for approve action
 * const specificDate = wfa.approvalDueDate({
 *   action: 'approve',
 *   dateType: 'relative',
 *   date: wfa.dataPill(_params.trigger.current.due_date, 'glide_date_time'),
 *   duration: 15,
 *   durationType: 'days',
 *   daysSchedule: '08fcd0830a0a0b2600079f56b1adb9ae',
 * })
 *
 * // Approval due date with actual date for reject action
 * const dueDate = wfa.approvalDueDate({
 *   action: 'reject',
 *   dateType: 'actual',
 *   date: wfa.dataPill(_params.trigger.current.due_date, 'glide_date_time'),
 * })
 *
 * // Approval due date with relative date for reject action
 * const specificDate = wfa.approvalDueDate({
 *   action: 'reject',
 *   dateType: 'relative',
 *   date: wfa.dataPill(_params.trigger.current.due_date, 'glide_date_time'),
 *   duration: 15,
 *   durationType: 'days',
 *   daysSchedule: '08fcd0830a0a0b2600079f56b1adb9ae',
 * })
 *
 * // Approval due date with actual date for cancel action
 * const dueDate = wfa.approvalDueDate({
 *   action: 'cancel',
 *   dateType: 'actual',
 *   date: wfa.dataPill(_params.trigger.current.due_date, 'glide_date_time'),
 * })
 *
 * ```
 */
export declare function ApprovalDueDate(approvalDueDate: ApprovalDueDateType): string
